settings.custom_liquid:
{%- liquid
  assign t = product.tags | join: ',' | downcase | split: ','
-%}
<div class="tb-product-badges">
  {%- if t contains 'one-of-a-kind' -%}<span class="is-dark">One of a kind</span>{%- endif -%}
  {%- if t contains 'everyday' -%}<span class="is-sand">Everyday</span>{%- elsif t contains 'occasion' -%}<span class="is-sand">Occasion</span>{%- endif -%}
  {%- if t contains 'charm-included' -%}<span class="is-sand">Charm included</span>{%- endif -%}
</div>

{%- assign coll = '' -%}
{%- for tag in product.tags -%}{%- assign d = tag | downcase -%}{%- if d contains 'collection-' -%}{%- assign coll = d | remove_first: 'collection-' -%}{%- break -%}{%- endif -%}{%- endfor -%}
<p class="tb-product-from">
  {%- if product.metafields.custom.subtitle != blank -%}{{ product.metafields.custom.subtitle | escape }}{%- endif -%}
  {%- if coll != '' -%}{%- if product.metafields.custom.subtitle != blank -%}, {% endif -%}<a href="{{ routes.collections_url }}/{{ coll }}">from the {{ coll | replace: '-', ' ' | capitalize }} collection</a>{%- endif -%}
</p>

{%- assign kit = product.metafields.custom.diy_kit.value -%}
{%- if kit != blank -%}
  <div class="tb-kit-callout"><p><strong>Love {{ product.title | escape }}?</strong> Make your own with the DIY kit, {{ kit.price | money }}.</p><a href="{{ kit.url }}">See the kit</a></div>
{%- endif -%}
